PROD=[['拉丁 pro-／prod- 向外 + agere 驱动 → prodigere','把东西耗掉、挥霍出去'],['拉丁 prodigus 挥霍的、慷慨的','钱财和资源大量流出']]
POLEM=[['希腊 polemos 战争 → polemikos 战争的','把争斗从战场移到文字与观点之间']]
