W=[
E('pseudo','英 /ˈsuːdəʊ/，也读 /ˈsjuːdəʊ/；美 /ˈsuːdoʊ/','假的；表面像真的；冒充的','挂着某种招牌，里面却没有相应的实质。','接希腊 pseudes 假的、pseudos 虚假，经拉丁化 pseudo- 进入英语。既能作构词成分，也有独立形容词、名词用法；开头 p 不发音。',[['希腊 pseudes／pseudos → 拉丁化 pseudo-','假的、表面上像的'],['英语 pseudo-；独立词 pseudo','组成各类词，也能直接说某种表现是假的']],'pseudo friendliness 是装出来的亲切，pseudo expertise 是有专家姿态却缺乏真本事。它通常带批评；但具体复合词如 pseudonym 只是化名，不自动意味着诈骗。','pseudo sophistication；pseudo expertise；pseudo 与 real 对照。','fake 更日常，pseudo 常带对某种身份或知识外观的质疑。anonymous 是匿名，与采用化名也不同。',('The article contrasts real expertise with pseudo expertise.','文章对比了真本事与徒有专家外表的做派。'),('His pseudo friendliness disappeared as soon as I declined the offer.','我一拒绝那项提议，他装出来的亲切就消失了。'),sources=['https://www.merriam-webster.com/dictionary/pseudo',ET('pseudo'),'https://en.wiktionary.org/wiki/pseudo']),
E('impudent','/ˈɪmpjədənt/','放肆的；无礼的；厚脸皮的','明明越过了礼貌边界，却毫不觉得不好意思。','拉丁 in- 不 + pudens 知耻、谦谨，形成 impudens，词干 impudent-，借入英语。这里 im- 是否定，pud- 接羞耻感。',IMP,'an impudent reply 是一声不把对方当回事的顶撞；an impudent grin 则可能是调皮又不服管的坏笑。语气有时也带对调皮的半责怪。','an impudent remark；an impudent grin；an impudent young man。','imprudent 多一个 r，意思是不谨慎；impudent 说不尊重别人。大胆 bold 本身可以是优点。',('The guest made an impudent remark about the host’s appearance.','客人放肆地评论了主人的外貌。'),('She answered the warning with an impudent grin.','面对警告，她却露出了一个不以为意的坏笑。'),sources=S('impudent',ET('impudent'))),
E('impudence','/ˈɪmpjədəns/','放肆；无礼；厚颜','把不该有的冒犯当成理所当然，连脸都不红。','拉丁 impudentia 厚颜、无耻独立借入，接 impudens。现代与 impudent 对应，历史不是只把英语形容词换尾。',PUD+[['拉丁 impudens → impudentia → 英语 impudence','不知羞的态度或表现']],'have the impudence to do something 常表达“竟敢这样做”的不满。它既可说一次行为，也可说一个人的态度，通常不可数。','have the impudence to ask；sheer impudence；tolerate someone’s impudence。','confidence 是自信，impudence 是冒犯他人的胆大。判断一个人是否无礼，也反映说话人对礼貌边界的看法。',('He had the impudence to ask for a reward after causing the damage.','他闯了祸，竟还厚着脸皮索要奖励。'),('The chair refused to tolerate such impudence during the meeting.','主持人不容许会议上出现这种放肆行为。'),sources=S('impudence',ET('impudence'))),
E('impudently','/ˈɪmpjədəntli/','放肆地；无礼地','说话或行动时，一副不在乎该有礼貌的样子。','英语 impudent + -ly。副词描述行为方式，不是另一条拉丁借词。',IMP+[['英语 impudent + -ly → impudently','将无礼这种性质用来说明怎么说、怎么做']],'answer impudently 可以是顶嘴；laugh impudently 可以是毫无顾忌地嘲弄。重点在态度，不只是音量大。','reply impudently；grin impudently；behave impudently。','rudely 泛指粗鲁，impudently 更容易带明知冒犯仍毫不害臊的感觉。loudly 只说明声音大。',('The boy impudently demanded a second prize.','那个男孩放肆地要求再给一份奖品。'),('She impudently interrupted the speaker to advertise her own business.','她无礼地打断发言者，为自己的生意做起了广告。'),sources=['https://dictionary.cambridge.org/us/dictionary/english/impudently','https://www.collinsdictionary.com/dictionary/english/impudently',ET('impudent')]),
E('repudiate','/rɪˈpjuːdieɪt/','坚决否认；拒绝接受；与……断绝关系','把某种说法、责任或关系明确推开：我不承认它。','确定接拉丁 repudium 拒绝、离婚 → repudiare → repudiatus，再进入英语；英语早期也有形容词用法。repudium 与 pudere 羞耻的联系只是解释之一，另有与 pes／ped- 脚有关的说法。',REP+[['拉丁 repudiatus → 英语 repudiate','早期被抛弃的；后来作动词，拒绝接受、否认关系']],'repudiate an allegation 是坚决否认指控；repudiate a former belief 则是不再接受过去的信念。涉及债务或合同，表示拒绝承认或履行，并不说明这种拒绝一定有效。','repudiate a claim；repudiate an ideology；repudiate a debt。','refute 通常指用理由或证据驳倒；repudiate 侧重公开、坚决地否认或拒绝，未必已经证明对方错。',('The spokesperson repudiated the claim that the report had been altered.','发言人坚决否认报告曾被修改的说法。'),('Years later, he repudiated the views he had defended in his youth.','多年后，他否定了自己年轻时曾维护的那些观点。'),sources=S('repudiate',ET('repudiate'))),
E('repudiation','/rɪˌpjuːdiˈeɪʃən/','坚决否认；拒绝承认；弃绝','把“我不接受、不承认”这一步当成一件明确的行动。','独立借拉丁 repudiatio／repudiationem，接 repudiare。现代可与 repudiate + -ion 对应，但不能只画成英语动词先造出名词；与 pudere 的远源关系仍不确定。',REP+[['拉丁 repudiatio／repudiationem → 英语 repudiation','早期解除婚姻关系；后指拒绝、否认、弃绝']],'a clear repudiation of violence 是明确反对并拒绝暴力；a repudiation of responsibility 是不认责任。of 后面通常接被拒绝的对象。','a public repudiation of something；a firm repudiation；repudiation of responsibility。','denial 更常说否认真假，repudiation 还可拒绝价值观或关系。disagreement 只是不同意，通常轻得多。',('Her statement was a clear repudiation of political violence.','她的声明明确表达了对政治暴力的反对与拒绝。'),('The letter contained an explicit repudiation of responsibility for the delay.','信中明确否认了对延误负有责任。'),sources=S('repudiation',ET('repudiation'))),
E('juxtaposition','/ˌdʒʌkstəpəˈzɪʃən/','并置；并列形成的对照','把两样东西放到一起，让差异或联系一下子显出来。','法语 juxtaposition 借入，来自拉丁 iuxta 在旁边 + 法语 position 放置。英语名词先于 juxtapose，不能倒过来把它讲成后者加 -ition。',JUX,'照片里新楼紧挨老屋，或者文章把承诺和结果放在相邻段落，都可以形成 juxtaposition。并置不必是物理空间，也可以是叙述安排。','the juxtaposition of A and B；a striking juxtaposition；in juxtaposition with。','comparison 是比较的广义活动；juxtaposition 更强调放在一起这个安排，让读者自己看出关系。它不保证两物绝对相反。',('The juxtaposition of luxury shops and empty homes is striking.','奢华商店与空置住宅的并置很引人注意。'),('The editor uses juxtaposition to expose the gap between promises and results.','编辑把承诺和结果并列起来，揭示两者的差距。'),sources=S('juxtaposition',ET('juxtaposition'))),
E('juxtapose','英 /ˌdʒʌkstəˈpəʊz/；美 /ˌdʒʌkstəˈpoʊz/','把……并置；并列对照','把两个画面、观点或物件摆到同一个视野里。','现代可拆 juxta- 在旁边 + pose 放置。历史上英语由较早 juxtaposition 反构，或经法语 juxtaposer 借入；这两种路线都不能写成英语动词先有。',[['拉丁 iuxta 在旁边 + position／poser 放置成分','形成法语与英语的并置词族'],['较早英语 juxtaposition 的反构，或法语 juxtaposer → 英语 juxtapose','把两样东西靠近摆放，常为比较或对照']],'juxtapose A with B 是常用句型。电影可以并置两个镜头，报告也可以把两个地区的数据并列，并不限于把实物搬过来。','juxtapose A with B；be juxtaposed with；juxtapose images。','combine 是合并，juxtapose 仍让两者各自可辨。两张照片并排展示，不一定合成了一张新照片。',('The exhibition juxtaposes early sketches with finished paintings.','展览把早期草图与完成的画作并列展示。'),('The article juxtaposes the official account with residents’ memories.','文章把官方说法与居民的回忆并列对照。'),sources=S('juxtapose',ET('juxtapose'),'https://www.collinsdictionary.com/dictionary/english/juxtapose')),
E('crass','/kræs/','粗俗的；愚蠢而不体谅人的','像一块没有磨细的石头，直接碰到别人的敏感处。','接拉丁 crassus 厚、粗、浓密，经法语相关形式进入英语。物理粗厚义在英语中少见，现代重点是言行缺少细腻判断。',CRASS,'a crass remark 可能在别人难过时开钱的玩笑；crass commercialism 则批评凡事只看赚钱。它不只是说语法错误，而是说没分寸、没品味。','a crass comment；crass insensitivity；crass commercialism。','blunt 可以直率却真诚；crass 更明确地批评粗俗、不顾感受。crude 也说粗糙，但使用范围更广。',('Joking about the layoffs was a crass mistake.','拿裁员开玩笑，是个很没分寸的错误。'),('She disliked the crass commercialism of the event.','她不喜欢那个活动赤裸而粗俗的商业气息。'),sources=S('crass',ET('crass'))),
E('crassly','/ˈkræsli/','粗俗地；愚蠢而无分寸地','做法很粗，完全没有留意别人会怎么感受。','英语 crass + -ly。常修饰 insensitive、commercial 等词，把缺乏体谅、缺乏品味这一层说得更明显。',CRASS+[['英语 crass + -ly → crassly','描述言行的粗俗、迟钝方式']],'crassly insensitive 不是一般不敏感，而是迟钝得令人反感。也可以直接修饰动词，说明某人说话做事很不得体。','crassly insensitive；crassly commercial；behave crassly。','carelessly 可能只是没注意；crassly 带更强的价值判断，批评缺乏分寸。',('The advertisement was crassly insensitive to people who had lost their jobs.','那则广告对失业者的处境毫无体谅，显得很不得体。'),('He crassly turned a private tribute into a sales pitch.','他很没分寸地把一场私人的致敬活动变成了推销。'),sources=S('crassly',ET('crass'))),
E('crassness','/ˈkræsnəs/','粗俗；无分寸；缺乏体谅','把言行中那种粗钝、不得体的性质单独拿出来说。','英语 crass + -ness，形成性质名词。不是另一个拉丁名词直接借入。',CRASS+[['英语 crass + -ness → crassness','粗俗、迟钝而不顾他人感受的性质']],'the crassness of a joke 说的不是笑话长短，而是它拿什么开玩笑、有没有顾及场合。通常不可数。','the crassness of a remark；sheer crassness；criticize someone’s crassness。','rudeness 是无礼的广义说法；crassness 还常涉及审美和判断粗糙。不是不够精致的东西都必须被说成 crassness。',('The crassness of the joke shocked the audience.','那个笑话的粗俗程度让观众吃了一惊。'),('The review criticized the campaign’s crassness rather than its budget.','评论批评的是那场宣传的没品味，而非预算大小。'),sources=S('crassness',ET('crass'))),
E('grease','/ɡriːs/','油脂；油垢；润滑脂；涂油','可以是黏在盘子上的油，也可以是让机器转得顺的稠油脂。','拉丁 crassus 厚、肥 → 重建通俗拉丁 *crassia 油脂，经古法语、盎格鲁法语进入英语。英语先有名词，再用作涂油的动词；不是由现代 crass 直接变出。',GREASE,'grease on a pan 是锅上的油脂或油垢；grease a pan 是给烤盘抹油。grease the wheels 还可以比喻使事情推进顺利，是否暗指不正当手段要看上下文。','cooking grease；a grease stain；grease a pan；grease the wheels。','oil 通常让人想到液态油，grease 更常是稠厚、半固体油脂或黏附的油污。fat 的范围更广，也可说食物营养成分。',('A layer of grease covered the extractor fan.','抽油烟机上覆盖着一层油垢。'),('Lightly grease the tin before pouring in the batter.','倒入面糊前，先给烤模薄薄涂一层油。'),sources=S('grease_1',ET('grease'),'https://www.oxfordlearnersdictionaries.com/definition/english/grease_2')),
E('greasy','/ˈɡriːsi/，也读 /ˈɡriːzi/','油腻的；沾满油的；滑腻的','手一摸就留油，或者吃起来满嘴油。','英语 grease + -y，去掉末尾 e。/s/ 与 /z/ 两种读法都常见，不需要见到 s 就只认一个音。',GREASE+[['英语 grease + -y → greasy','含油很多、表面沾油；也可比喻油滑讨好']],'greasy food 常带不喜欢的评价；greasy hair 说头发油。形容一个人 greasy，可能是在批评其油滑奉承，并不是在说真的沾了油。','greasy fingers；greasy food；greasy hair；a greasy mark。','oily 有时较中性，如 oily fish；greasy 更容易带黏腻、不舒服的感觉。slippery 说滑，不保证是油造成。',('He left greasy fingerprints on the glass door.','他在玻璃门上留下了油乎乎的指印。'),('The chips were too greasy for my taste.','那些炸薯条对我来说太油腻了。'),sources=S('greasy',ET('greasy'))),
]
