DEFERRED={'pudendum':'较专门的解剖用词，暂略。','crassitude':'古旧、罕见的性质名词，先学 crassness。','crassulaceous':'专门植物分类形容词，暂略。','hybris':'hubris 的另一拼法，已在 hubris 词条合并说明。','hybristic':'hubristic 的另一拼法，已在 hubristic 词条合并说明。','fuscous':'罕用色彩、形态描写词，先掌握通用 obfuscate 词族。','infuscate':'古旧的使变暗动词与形容词，暂略。','infuscation':'冷门的变暗、暗色斑纹术语，暂略。','polemarch':'古希腊官职专名，暂略。','polemology':'专门学科名称，暂略。'}
ALREADY={'pseudonym','pseudonymous','pseudoscience','pseudoscientific','obfuscate','obfuscation'}
CATALOG={r['id']:r for r in json.loads(Path('.cache/catalog.json').read_text())}
def rootwords(i,extra=()):return list(dict.fromkeys([w for w in ASSIGN['roots'][i]['family'] if w not in DEFERRED and '-' not in w]+list(extra)))
def rootexclude(i):
 r=ASSIGN['roots'][i];c=CATALOG[r['id']];return {w:DEFERRED[w] for w in set(r['family'])|set(c['family'])|set(c['words'])|set(c['unmatched']) if w in DEFERRED}
PSEUD_ROOT=dict(id='C1147',meaning='假的；非真正的；表面像的',core='看上去是某种东西，实质或身份却不是字面所称的那个。',image='希腊 pseudes／pseudos → pseudo-；与名字成分组成 pseudonym、pseudonymous；与 science／scientific 组成伪科学词。',intro='这里的“假”不能一概等于骗人：pseudonym 是化名，可以用于写作或保护隐私；pseudoscience 则批评披着科学外衣却不符合科学方法。先看后面接的对象，再判断具体语气。',forms='开头 p 通常不发音。pseudo- 常作构词成分，也有独立词 pseudo；pseudonymous 有自己的古典借入线，不只是在现代 pseudonym 后加后缀。',branches=[['表面像真的','pseudo'],['名称与身份','pseudonym, pseudonymous'],['科学外观与实质','pseudoscience, pseudoscientific']],contrasts='anonymous 是不署明身份，pseudonymous 是使用另一名称；研究尚未证实，不自动等于 pseudoscience，要看其方法与证据姿态。',practice='解释笔名为什么可以是 pseudonym 却不涉及诈骗；再说明 pseudo expertise 为什么常带批评。',words=rootwords(238,['pseudoscience','pseudoscientific','pseudonymous']),exclude=rootexclude(238))
PUDE_ROOT=dict(id='C1164',meaning='羞耻；无礼；另列拒绝的争议支线',core='确定的一支是“不觉得该害臊”；另一支 repudiate 的“拒绝、抛弃”不能硬接成同一故事。',image='拉丁 pudere → pudens／pudent-；in- + pudent- → impudent；impudentia → impudence；独立争议支线 repudium → repudiare → repudiate／repudiation。',intro='impudent 是态度，impudence 是这种无礼，impudently 说明行为方式。repudiate 与 repudiation 在日常正式阅读很有用，但它们与 pudere 的远源关系有分歧，这里保留为对照支线。',forms='in- 在 p 前变 im-。impudent 不要与 imprudent 不谨慎混淆。repudiate 历史上可追到拉丁 repudium；其更远分析有人联系羞耻，也有人联系脚，不能把猜测当定论。',branches=[['不知害臊的无礼','impudent, impudence, impudently'],['拒绝与断绝：来源关联未定','repudiate, repudiation']],contrasts='repudiate 侧重拒绝接受或承认；refute 更强调证据上的驳倒。两组都可带强烈语气，却不是同一种心理动作。',practice='把 an impudent reply 改写成 answered impudently；再用 repudiate 写拒绝某项说法，说明它是否已经证明说法为假。',words=rootwords(239),exclude=rootexclude(239))
JUX_ROOT=dict(id='C0630',meaning='在旁边；并置',core='两样东西一靠近，原本不明显的差异或联系就跳出来。',image='拉丁 iuxta 在旁边 + 法语 position → juxtaposition → 英语名词；英语名词反构或法语 juxtaposer → juxtapose。',intro='juxtaposition 是并置这种安排，juxtapose 是把它们并置的动作。可以摆照片，也可以并列文字、观点、数据；关键是让它们同处一个可比较的视野。',forms='juxta- 接“旁边”，不是 just 的变体。英语 juxtaposition 比 juxtapose 更早，现代动名词对应并不代表历史总是动词先有。',branches=[['安排或结果','juxtaposition'],['主动并置','juxtapose']],contrasts='combine 可以融合成一个整体；juxtapose 通常仍让两者各自可辨。它常为了对比，却不要求两者完全相反。',practice='选两张年代不同的城市照片，用 juxtapose A with B 描述展示，再用 the juxtaposition of A and B 说明效果。',words=rootwords(240),exclude=rootexclude(240))
CRASS_ROOT=dict(id='C0267',meaning='厚；粗；肥厚与油脂',core='同一古老“粗厚”画面，一边成了言行不细腻，一边保留成黏厚油脂。',image='拉丁 crassus → 法语相关形式 → crass → crassly／crassness；另一支 *crassia → 古法语 gresse、盎格鲁法语 grece → grease → greasy。',intro='crass 一组判断言行是否粗俗、无分寸；grease 一组说油脂、油污或涂油。它们有共同的拉丁背景，不是英语里先有粗俗，再把这个词改成油。',forms='crass 的 a 常读 /æ/；grease 的 ea 读 /iː/。greasy 的 /s/ 与 /z/ 两种读法都常见。*crassia 的星号表示历史重建形式。',branches=[['言行粗俗','crass, crassly, crassness'],['油脂与涂油','grease, greasy']],contrasts='blunt 可以坦率而善意，crass 明显批评缺少分寸。greasy 常含油腻不适感，oily 在 oily fish 等搭配中可很中性。',practice='分别写一条关于言语冒犯和一条关于厨房油污的句子，看看同源背景如何通向不同现代用法。',words=rootwords(241),exclude=rootexclude(241))
HYBR_ROOT=dict(id='C0575',meaning='放肆；傲慢；越界的自负',core='不是普通自信，而是膨胀到觉得自己无需听警告、无需受规则限制。',image='希腊 hybris／hubris → hybrizein → hybristikos → 英语 hubristic；希腊名词独立借入或从较早形容词反构 → 英语 hubris。',intro='hubris 常见于历史、文学和商业评论，描述狂妄自负；hubristic 描述相应的行为和态度。古希腊词义还包括侮辱、放肆暴行，不能把全部历史压成“得罪神所以失败”。',forms='hybris、hybristic 是可见的另一拼法，合并在常用 hubris、hubristic 下。hubristic 的英语记录更早，词尾更长不代表一定较晚。',branches=[['狂妄这种态度','hubris'],['具有这种态度的言行','hubristic']],contrasts='confidence 可合理、积极；hubris 已含过度的评价。词根写作 hybr- 也不表示见到相同字母就能无条件纳入这条词源。',practice='用两个句子对比 confident 和 hubristic；解释忽视风险为何常被评论者称为 hubris。',words=rootwords(242),exclude=rootexclude(242))
EMUL_ROOT=dict(id='C0371',meaning='效仿竞争；争取达到相同表现',core='看到对方做得好，努力让自己也做到；技术上则让另一环境实现相似行为。',image='拉丁 aemulus → aemulari；aemulatio 经法语／拉丁 → emulation；aemulatus 或较早 emulation 反构 → emulate；拉丁 aemulator → emulator。',intro='emulate 说动作，emulation 说过程，emulator 说人或工具。计算机用法是后来发展，并不表示这三个词原本都为软件发明。',forms='emulation 的英语记录早于 emulate；emulator 也有独立拉丁人物名词来源。现代能看出 -ion、-or 对应，历史仍需保留各条借入路径。',branches=[['效仿的动作','emulate'],['过程与技术','emulation'],['效仿者与工具','emulator']],contrasts='imitate 可以只学声音或样子，emulate 常希望达到类似表现。技术中的 simulation、emulation 有重叠，不能仅靠中文“模拟器”区分所有实现。',practice='先用 emulate 写向榜样学习，再用 emulator 写旧软件运行，说明两者共享的核心是什么。',words=rootwords(243),exclude=rootexclude(243))
FUSC_ROOT=dict(id='C0462',meaning='暗；使模糊不清',core='像给内容蒙上一层暗色，使人难看清真正重点。',image='拉丁 fuscus 暗 → fuscare 使暗 → obfuscare；obfuscatus 等 → obfuscate；拉丁名词 obfuscatio → 英语 obfuscation。',intro='最实用的是 obfuscate 和 obfuscation：说话绕、文字堆得复杂，让重点变难懂。字面上的暗发展成理解上的不清楚；代码混淆也是相似画面。',forms='fusc- 不必单独作为英语词使用。obfuscation 的名词有自己的拉丁借入路线，不只看成现代动词加后缀。',branches=[['使理解变难','obfuscate'],['混淆这种做法','obfuscation']],contrasts='clarification 是澄清；obfuscation 让内容更难懂。代码混淆不等于加密：难阅读与必须有密钥才能还原不是一回事。',practice='把一段绕来绕去的解释改写清楚，再用 obfuscation 描述原来的问题。',words=rootwords(244),exclude=rootexclude(244))
PRODIG_ROOT=dict(id='C1133',meaning='往外驱散；耗费；挥霍',core='资源像被不断往外推，给得、花得超过需要。',image='拉丁 pro-／prod- + agere → prodigere → prodigus；prodigalis 与 prodigalitas 经法语、拉丁路线分别连接 prodigal 和较早的 prodigality。',intro='prodigal 最常在浪子典故和挥霍语境里遇到；prodigality 是正式的性质名词。浪子归来的联想来自故事，不是 prodigal 所有用法的字面义。',forms='prod- 是这里 pro- 的历史形式，后面接 agere 驱动。不要把 prodigy 神童、prodigious 惊人的仅凭相似拼写放进这条线。prodigality 在英语中更早，词史不等于现代拆分顺序。',branches=[['人物与行为的性质','prodigal'],['浪费的做法与习惯','prodigality']],contrasts='generosity 可以恰当而美好；prodigality 往往强调过度。prodigal son 典故中有归家，但 prodigal spending 只说挥霍。',practice='解释 prodigal son 与 child prodigy 的差别；再用 prodigal spending 写一个无需涉及家庭故事的句子。',words=rootwords(245),exclude=rootexclude(245))
